package config

import "encoding/json"

type Config struct {
	Name string
}

func Parse(s string) (Config, error) {
	var c Config
	if err := json.Unmarshal([]byte(s), &c); err != nil {
		return Config{}, err
	}
	return c, nil
}

func helper(s string) string {
	return s
}

